<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue';
import { Head, Link, usePage } from '@inertiajs/vue3';
import { formatPrice } from '@/data/products';
import { getCartStorageKey, migrateLegacyCart, readCart, type CartItem } from '@/lib/cart';

type PaypalSdkInstance = {
    findEligibleMethods: (options?: { currencyCode?: string }) => Promise<{ isEligible: (method: string) => boolean }>;
    createPayPalOneTimePaymentSession: (options: Record<string, unknown>) => unknown;
};
declare global { interface Window { paypal?: { createInstance: (options: Record<string, unknown>) => Promise<PaypalSdkInstance> }; } }
type Province = { code: number; name: string; wards?: Ward[] };
type Ward = { code: number; name: string; province_code?: number };
type VatInvoiceForm = { requested: boolean; companyName: string; taxCode: string; address: string; email: string };
const page = usePage();
const authUser = computed(() => (page.props as any).auth?.user ?? null);
const userId = computed<number | null>(() => authUser.value?.id ? Number(authUser.value.id) : null);
const cart = ref<CartItem[]>([]); const submitted = ref(false); const orderCode = ref(''); const shippingError = ref(''); const vatError = ref(''); const orderError = ref(''); const paypalError = ref(''); const paypalLoading = ref(false); const paypalReady = ref(false); const paypalEligible = ref(false); const paypalContainer = ref<HTMLElement | null>(null); const paypalButton = ref<HTMLElement | null>(null); const paypalSession = ref<{ start: (options: Record<string, unknown>, order: Promise<{ orderId: string }>) => Promise<unknown> } | null>(null); const paypalClientId = String(import.meta.env.VITE_PAYPAL_CLIENT_ID ?? '').trim();
const vatProvinces = ref<Province[]>([]); const vatWards = ref<Ward[]>([]); const vatSelectedProvince = ref(''); const vatSelectedWard = ref(''); const vatAddressDetail = ref(''); const vatAddressLoading = ref(false); const vatAddressError = ref('');
const shippingWards = ref<Ward[]>([]); const shippingSelectedProvince = ref(''); const shippingSelectedWard = ref(''); const shippingAddressDetail = ref(''); const shippingAddressHydrating = ref(false);
const form = ref({ name:'',phone:'',email:'',address:'',note:'',payment:'cod',vatInvoice:{requested:false,companyName:'',taxCode:'',address:'',email:''} as VatInvoiceForm });
const COD_SHIPPING_FEE=30000; const VND_TO_USD=25000;
function loadCart():void{if(!userId.value){cart.value=[];return;}migrateLegacyCart(userId.value);cart.value=readCart(userId.value);form.value.name=authUser.value?.name??'';form.value.phone=authUser.value?.phone??'';form.value.email=authUser.value?.email??'';form.value.address=authUser.value?.address??'';shippingAddressDetail.value=authUser.value?.address??'';}
function normalizeAddressPart(value:string):string{return value.trim().toLocaleLowerCase('vi-VN').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();}
function buildShippingAddress():string{return [shippingAddressDetail.value.trim(),shippingSelectedWard.value.trim(),shippingSelectedProvince.value.trim()].filter(Boolean).join(', ');}
function syncShippingAddress():void{if(shippingAddressHydrating.value)return;form.value.address=buildShippingAddress();}
function findAddressSuffix(parts:string[], names:string[]):string{for(let index=parts.length-1;index>=0;index-=1){const candidate=parts.slice(index).join(', ');const normalizedCandidate=normalizeAddressPart(candidate);const match=names.find((name)=>normalizeAddressPart(name)===normalizedCandidate);if(match)return match;}return '';}
async function loadShippingWards(provinceName:string):Promise<void>{shippingWards.value=[];shippingSelectedWard.value='';if(!provinceName){syncShippingAddress();return;}const province=vatProvinces.value.find((item)=>item.name===provinceName);if(!province)return;if(province.wards?.length){shippingWards.value=province.wards;syncShippingAddress();return;}try{const response=await fetch(`https://provinces.open-api.vn/api/v2/p/${province.code}?depth=2`);if(!response.ok)throw new Error('address-api');const data=await response.json();shippingWards.value=Array.isArray(data.wards)?data.wards:[];}catch{vatAddressError.value='Không thể tải danh sách phường/xã. Vui lòng thử lại.';}syncShippingAddress();}
async function hydrateShippingAddress():Promise<void>{const savedAddress=String(authUser.value?.address??'').trim();if(!savedAddress||!vatProvinces.value.length)return;shippingAddressHydrating.value=true;const parts=savedAddress.split(',').map((part)=>part.trim()).filter(Boolean);const province=findAddressSuffix(parts,vatProvinces.value.map((item)=>item.name));if(!province){shippingAddressDetail.value=savedAddress;form.value.address=savedAddress;shippingAddressHydrating.value=false;return;}shippingSelectedProvince.value=province;const provinceData=vatProvinces.value.find((item)=>item.name===province);if(!provinceData){shippingAddressDetail.value=savedAddress;form.value.address=savedAddress;shippingAddressHydrating.value=false;return;}if(provinceData.wards?.length)shippingWards.value=provinceData.wards;else{try{const response=await fetch(`https://provinces.open-api.vn/api/v2/p/${provinceData.code}?depth=2`);if(response.ok){const data=await response.json();shippingWards.value=Array.isArray(data.wards)?data.wards:[];}}catch{shippingWards.value=[];}}const ward=findAddressSuffix(parts.slice(0,-1),shippingWards.value.map((item)=>item.name));if(ward){shippingSelectedWard.value=ward;const provinceIndex=parts.findIndex((part)=>normalizeAddressPart(part)===normalizeAddressPart(province));const wardIndex=parts.findIndex((part)=>normalizeAddressPart(part)===normalizeAddressPart(ward));shippingAddressDetail.value=parts.filter((_,index)=>index!==provinceIndex&&index!==wardIndex).join(', ');}else{shippingAddressDetail.value=parts.slice(0,-1).join(', ');}form.value.address=buildShippingAddress()||savedAddress;shippingAddressHydrating.value=false;}
async function loadVatWards(provinceName:string):Promise<void>{vatWards.value=[];vatSelectedWard.value='';if(!provinceName){syncVatAddress();return;}const province=vatProvinces.value.find((item)=>item.name===provinceName);if(!province)return;if(province.wards?.length){vatWards.value=province.wards;syncVatAddress();return;}try{const response=await fetch(`https://provinces.open-api.vn/api/v2/p/${province.code}?depth=2`);if(!response.ok)throw new Error('address-api');const data=await response.json();vatWards.value=Array.isArray(data.wards)?data.wards:[];}catch{vatAddressError.value='Không thể tải danh sách phường/xã. Vui lòng thử lại.';}syncVatAddress();}
async function loadVatAddressOptions():Promise<void>{vatAddressLoading.value=true;vatAddressError.value='';try{const response=await fetch('https://provinces.open-api.vn/api/v2/?depth=2');if(!response.ok)throw new Error('address-api');const data=await response.json();vatProvinces.value=Array.isArray(data)?data:[];}catch{vatAddressError.value='Không thể tải danh sách tỉnh/thành phố. Vui lòng thử lại.';}finally{vatAddressLoading.value=false;}}
function syncVatAddress():void{form.value.vatInvoice.address=[vatAddressDetail.value.trim(),vatSelectedWard.value.trim(),vatSelectedProvince.value.trim()].filter(Boolean).join(', ');}
watch([vatSelectedProvince,vatSelectedWard,vatAddressDetail],syncVatAddress); watch([shippingSelectedProvince,shippingSelectedWard,shippingAddressDetail],syncShippingAddress);
const itemCount=computed(()=>cart.value.reduce((sum,item)=>sum+item.quantity,0)); const subtotal=computed(()=>cart.value.reduce((sum,item)=>sum+item.price*item.quantity,0)); const shippingFee=computed(()=>form.value.payment==='cod'&&cart.value.length?COD_SHIPPING_FEE:0); const totalShipping=computed(()=>shippingFee.value); const total=computed(()=>subtotal.value+totalShipping.value); const paypalRateLabel=computed(()=>`1 USD = ${VND_TO_USD.toLocaleString('vi-VN')} VND`); const paypalUsd=computed(()=>Math.max(1,Math.round((total.value/VND_TO_USD)*100)/100));
function validateShipping():boolean{if(!form.value.name.trim()||!form.value.phone.trim()||!form.value.address.trim()){shippingError.value='Vui lòng nhập đầy đủ họ tên, số điện thoại và địa chỉ nhận hàng.';return false;}if(vatProvinces.value.length&&(!shippingSelectedProvince.value||!shippingSelectedWard.value||!shippingAddressDetail.value.trim())){shippingError.value='Vui lòng chọn đầy đủ tỉnh/thành phố, phường/xã và nhập số nhà, tên đường.';return false;}shippingError.value='';return true;}
function validateVatInvoice():boolean{if(!form.value.vatInvoice.requested){vatError.value='';return true;}syncVatAddress();const vat=form.value.vatInvoice;if(!vat.companyName.trim()){vatError.value='Vui lòng nhập tên công ty hoặc đơn vị.';return false;}if(!vat.taxCode.trim()){vatError.value='Vui lòng nhập mã số thuế.';return false;}if(!vatSelectedProvince.value||!vatSelectedWard.value||!vatAddressDetail.value.trim()){vatError.value='Vui lòng chọn đầy đủ tỉnh/thành phố, phường/xã và nhập số nhà, tên đường.';return false;}if(!vat.email.trim()){vatError.value='Vui lòng nhập Email nhận hóa đơn.';return false;}vatError.value='';return true;}
function clearUserCart():void{if(!userId.value)return;localStorage.removeItem(getCartStorageKey(userId.value));window.dispatchEvent(new Event('techstore-cart-updated'));}
async function persistOrder(payment:string,paypalOrderId:string|null=null){const response=await fetch('/orders',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},body:JSON.stringify({customer:{name:form.value.name,phone:form.value.phone,email:form.value.email,address:form.value.address,note:form.value.note},items:cart.value,subtotal:subtotal.value,shipping:shippingFee.value,total_shipping:totalShipping.value,total:total.value,payment,paypal_order_id:paypalOrderId,vat_invoice:{requested:form.value.vatInvoice.requested,company_name:form.value.vatInvoice.companyName,tax_code:form.value.vatInvoice.taxCode,address:form.value.vatInvoice.address,email:form.value.vatInvoice.email}})});const data=await response.json().catch(()=>({}));if(!response.ok||!data.order?.code)throw new Error(data.message??'Không thể lưu đơn hàng.');return data.order;}
async function saveOrder(payment:string,paypalOrderId:string|null=null):Promise<void>{orderError.value='';if(!validateShipping()||!validateVatInvoice())return;try{const order=await persistOrder(payment,paypalOrderId);orderCode.value=order.code;clearUserCart();submitted.value=true;window.scrollTo({top:0,behavior:'smooth'});}catch(error){orderError.value=error instanceof Error?error.message:'Không thể lưu đơn hàng.';throw error;}}
async function submitCod():Promise<void>{if(!cart.value.length)return;try{await saveOrder('cod');}catch{}}
function csrfToken():string{return document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';}
function loadPaypalSdk():Promise<void>{if(window.paypal)return Promise.resolve();if(!paypalClientId)return Promise.reject(new Error('TechStore chưa có PayPal Sandbox Client ID.'));return new Promise((resolve,reject)=>{const existing=document.querySelector<HTMLScriptElement>('script[data-techstore-paypal-v6]');if(existing){existing.addEventListener('load',()=>resolve(),{once:true});existing.addEventListener('error',()=>reject(new Error('Không tải được PayPal Sandbox.')),{once:true});return;}const script=document.createElement('script');script.src='https://www.sandbox.paypal.com/web-sdk/v6/core';script.async=true;script.dataset.techstorePaypalV6='true';script.onload=()=>resolve();script.onerror=()=>reject(new Error('Không tải được PayPal Sandbox.'));document.head.appendChild(script);});}
async function createPaypalOrder():Promise<{orderId:string}>{if(!validateShipping()||!validateVatInvoice())throw new Error(shippingError.value||vatError.value);const response=await fetch('/paypal/orders',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':csrfToken()},body:JSON.stringify({amount_vnd:total.value})});const data=await response.json().catch(()=>({}));if(!response.ok||!data.id)throw new Error(data.message??'Không thể tạo đơn PayPal Sandbox.');return{orderId:String(data.id)};}
async function capturePaypalOrder({orderId}:{orderId:string}):Promise<void>{const response=await fetch(`/paypal/orders/${encodeURIComponent(orderId)}/capture`,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrfToken()}});const data=await response.json().catch(()=>({}));if(!response.ok||data.status!=='COMPLETED')throw new Error(data.message??'PayPal Sandbox chưa xác nhận thanh toán.');await saveOrder('paypal-sandbox',orderId);paypalLoading.value=false;}
let paypalSetupVersion=0;
async function setupPaypal():Promise<void>{if(!paypalClientId||form.value.payment!=='paypal')return;const setupVersion=++paypalSetupVersion;paypalReady.value=false;paypalEligible.value=false;paypalError.value='';try{await loadPaypalSdk();if(setupVersion!==paypalSetupVersion||form.value.payment!=='paypal')return;if(!window.paypal)throw new Error('PayPal Sandbox SDK chưa sẵn sàng.');const sdk=await window.paypal.createInstance({clientId:paypalClientId,components:['paypal-payments'],pageType:'checkout'});const eligibility=await sdk.findEligibleMethods({currencyCode:'USD'});if(setupVersion!==paypalSetupVersion||form.value.payment!=='paypal')return;paypalEligible.value=eligibility.isEligible('paypal');if(!paypalEligible.value){paypalError.value='PayPal Sandbox không xác định được phương thức PayPal phù hợp với môi trường hiện tại.';return;}await nextTick();if(setupVersion!==paypalSetupVersion||form.value.payment!=='paypal'||!paypalContainer.value)return;paypalSession.value=sdk.createPayPalOneTimePaymentSession({onApprove:capturePaypalOrder,onCancel:()=>{paypalLoading.value=false;paypalError.value='Bạn đã hủy thanh toán PayPal Sandbox.';},onError:(error:unknown)=>{paypalLoading.value=false;console.error(error);paypalError.value='PayPal Sandbox gặp lỗi. Vui lòng thử lại.';}}) as typeof paypalSession.value;const button=document.createElement('paypal-button');button.setAttribute('type','pay');button.addEventListener('click',async()=>{if(!validateShipping()||!validateVatInvoice()||!paypalSession.value)return;paypalLoading.value=true;paypalError.value='';try{await paypalSession.value.start({presentationMode:'auto'},createPaypalOrder());}catch(error){paypalLoading.value=false;paypalError.value=error instanceof Error?error.message:'Không thể mở PayPal Sandbox.';}});paypalButton.value=button;paypalContainer.value.replaceChildren(button);paypalReady.value=true;}catch(error){if(setupVersion!==paypalSetupVersion||form.value.payment!=='paypal')return;paypalReady.value=false;paypalError.value=error instanceof Error?error.message:'Không thể khởi tạo PayPal Sandbox.';}}
function selectPayment(payment:string):void{form.value.payment=payment;paypalSetupVersion+=1;if(payment==='cod'){paypalReady.value=false;paypalEligible.value=false;paypalSession.value=null;paypalButton.value=null;paypalLoading.value=false;paypalError.value='';return;}paypalSession.value=null;paypalButton.value=null;void nextTick(setupPaypal);}
watch(()=>form.value.payment,(payment)=>{if(payment==='paypal')void nextTick(setupPaypal);});
onMounted(async()=>{loadCart();await loadVatAddressOptions();await hydrateShippingAddress();});
</script>

<template>
    <Head title="Thanh toán" />
    <div class="checkout-page"><div class="container checkout-container"><nav class="checkout-breadcrumb"><Link href="/">Trang chủ</Link><i class="bi bi-chevron-right"/><Link href="/cart">Giỏ hàng</Link><i class="bi bi-chevron-right"/><span>Thanh toán</span></nav>
        <section v-if="submitted" class="checkout-success"><div class="success-icon"><i class="bi bi-check-lg"/></div><span class="checkout-kicker">ĐẶT HÀNG THÀNH CÔNG</span><h1>Cảm ơn bạn đã mua hàng!</h1><p>Đơn hàng <strong>{{ orderCode }}</strong> đã được ghi nhận.</p><div class="success-summary"><span>Tổng thanh toán</span><strong>{{ formatPrice(total) }}</strong></div><div v-if="form.payment === 'paypal-sandbox'" class="sandbox-success"><i class="bi bi-shield-check"/><span>Thanh toán đã được xác nhận trên <strong>PayPal Sandbox</strong>. Đây là giao dịch thử nghiệm, không chuyển tiền thật.</span></div><Link href="/products" class="success-btn">Tiếp tục mua sắm <i class="bi bi-arrow-right"/></Link></section>
        <template v-else-if="cart.length"><div class="checkout-heading"><div><span class="checkout-kicker">TECHSTORE · THANH TOÁN</span><h1>Đặt hàng &amp; vận chuyển</h1><p>Thông tin cá nhân đã lưu sẽ được tự động điền vào biểu mẫu.</p></div><span class="checkout-count"><i class="bi bi-bag"/> {{ itemCount }} sản phẩm</span></div>
            <form class="row g-4" @submit.prevent="submitCod"><section class="col-lg-7"><div class="checkout-card"><div class="checkout-card-title"><span>1</span><div><strong>Thông tin nhận hàng</strong><small>Tên, số điện thoại và địa chỉ dùng cho giao hàng.</small></div></div><div class="saved-profile-note"><i class="bi bi-person-check-fill"/><span>Đã tự động điền từ <strong>Thông tin cá nhân</strong>. Bạn vẫn có thể chỉnh sửa cho riêng đơn hàng này.</span></div><div class="row g-3"><div class="col-md-6"><label>Họ và tên <b>*</b></label><input v-model="form.name" required type="text" autocomplete="name" placeholder="Nguyễn Văn A"/></div><div class="col-md-6"><label>Số điện thoại <b>*</b></label><input v-model="form.phone" required type="tel" autocomplete="tel" pattern="[0-9+ .-]{8,20}" placeholder="0901 234 567"/></div><div class="col-12"><label>Email</label><input v-model="form.email" type="email" autocomplete="email" placeholder="email@example.com"/></div><div class="col-12"><label>Địa chỉ nhận hàng <b>*</b></label><div class="row g-3"><div class="col-md-6"><select v-model="shippingSelectedProvince" @change="loadShippingWards(shippingSelectedProvince)" :disabled="vatAddressLoading" class="shipping-address-select" required><option value="">{{ vatAddressLoading ? 'Đang tải...' : 'Chọn tỉnh / thành phố' }}</option><option v-for="province in vatProvinces" :key="province.code" :value="province.name">{{ province.name }}</option></select></div><div class="col-md-6"><select v-model="shippingSelectedWard" :disabled="!shippingSelectedProvince || vatAddressLoading" class="shipping-address-select" required><option value="">{{ shippingSelectedProvince ? 'Chọn phường / xã' : 'Chọn tỉnh trước' }}</option><option v-for="ward in shippingWards" :key="ward.code" :value="ward.name">{{ ward.name }}</option></select></div><div class="col-12"><input v-model="shippingAddressDetail" required type="text" maxlength="250" autocomplete="street-address" placeholder="Số nhà, tên đường"/></div></div><div v-if="form.address" class="shipping-address-preview"><i class="bi bi-geo-alt-fill"/><span>{{ form.address }}</span></div></div><div class="col-12"><label>Ghi chú</label><textarea v-model="form.note" rows="2" placeholder="Ví dụ: Giao giờ hành chính..."/></div></div><div v-if="shippingError" class="checkout-error"><i class="bi bi-exclamation-circle"/> {{ shippingError }}</div></div>
                <div class="checkout-card vat-card"><div class="checkout-card-title"><span><i class="bi bi-receipt-cutoff"/></span><div><strong>Xuất hóa đơn VAT</strong><small>Bạn có thể chọn xuất hóa đơn VAT cho đơn hàng này.</small></div></div><label class="vat-toggle-row"><input v-model="form.vatInvoice.requested" type="checkbox" @change="vatError = ''"/><span class="vat-toggle-ui" aria-hidden="true"><i class="bi bi-check"/></span><span class="vat-toggle-copy"><strong>Tôi muốn xuất hóa đơn VAT</strong><small>Không thêm phí vào đơn hàng. Thông tin xuất hóa đơn sẽ được lưu cùng đơn.</small></span></label>
                    <div v-if="form.vatInvoice.requested" class="vat-fields"><div class="vat-info-banner"><i class="bi bi-info-circle-fill"/><span>Vui lòng nhập chính xác thông tin doanh nghiệp/đơn vị để lập hóa đơn. Địa chỉ sử dụng đơn vị hành chính Việt Nam sau sáp nhập từ 01/07/2025.</span></div><div class="row g-3"><div class="col-12"><label>Tên công ty / đơn vị <b>*</b></label><input v-model="form.vatInvoice.companyName" type="text" maxlength="255" placeholder="Công ty TNHH TechStore"/></div><div class="col-md-6"><label>Mã số thuế <b>*</b></label><input v-model="form.vatInvoice.taxCode" type="text" maxlength="32" placeholder="0101234567"/></div><div class="col-md-6"><label>Email nhận hóa đơn <b>*</b></label><input v-model="form.vatInvoice.email" type="email" maxlength="255" placeholder="ketoan@congty.vn"/></div><div class="col-md-6"><label>Tỉnh / Thành phố <b>*</b></label><select v-model="vatSelectedProvince" @change="loadVatWards(vatSelectedProvince)" :disabled="vatAddressLoading" class="vat-address-select"><option value="">{{ vatAddressLoading ? 'Đang tải...' : 'Chọn tỉnh / thành phố' }}</option><option v-for="province in vatProvinces" :key="province.code" :value="province.name">{{ province.name }}</option></select></div><div class="col-md-6"><label>Phường / Xã <b>*</b></label><select v-model="vatSelectedWard" :disabled="!vatSelectedProvince || vatAddressLoading" class="vat-address-select"><option value="">{{ vatSelectedProvince ? 'Chọn phường / xã' : 'Chọn tỉnh trước' }}</option><option v-for="ward in vatWards" :key="ward.code" :value="ward.name">{{ ward.name }}</option></select></div><div class="col-12"><label>Số nhà, tên đường <b>*</b></label><input v-model="vatAddressDetail" type="text" maxlength="250" placeholder="Ví dụ: 25 Nguyễn Văn Linh" autocomplete="street-address"/></div></div><div v-if="form.vatInvoice.address" class="vat-address-preview"><i class="bi bi-geo-alt-fill"/><span>{{ form.vatInvoice.address }}</span></div><div v-if="vatAddressError" class="checkout-error"><i class="bi bi-exclamation-circle"/> {{ vatAddressError }}</div><div v-if="vatError" class="checkout-error"><i class="bi bi-exclamation-circle"/> {{ vatError }}</div></div></div><div v-if="orderError" class="checkout-error checkout-error-global"><i class="bi bi-exclamation-circle"/> {{ orderError }}</div></section>
                <aside class="col-lg-5"><div class="checkout-order-card"><div class="order-card-title">Tóm tắt đơn hàng</div><div v-for="item in cart" :key="item.id" class="order-item"><div class="order-image"><img :src="item.image" :alt="item.name"/></div><div class="order-info"><strong>{{ item.name }}</strong><small>{{ item.quantity }} × {{ formatPrice(item.price) }}</small></div><b>{{ formatPrice(item.price * item.quantity) }}</b></div><div class="order-divider"/><div class="order-total-line"><span>Tạm tính</span><strong>{{ formatPrice(subtotal) }}</strong></div><div class="order-total-line"><span>Phí vận chuyển</span><strong>{{ formatPrice(totalShipping) }}</strong></div><div class="order-total-line order-total-final"><span>Tổng cộng</span><strong>{{ formatPrice(total) }}</strong></div><div class="payment-block"><div class="payment-title">Phương thức thanh toán</div><button type="button" :class="['payment-option',{active:form.payment==='cod'}]" @click="selectPayment('cod')"><span><i class="bi bi-cash-coin"/><strong>Thanh toán khi nhận hàng</strong></span><i class="bi bi-check-circle-fill"/></button><button type="button" :class="['payment-option',{active:form.payment==='paypal'}]" @click="selectPayment('paypal')"><span><i class="bi bi-paypal"/><strong>PayPal Sandbox</strong></span><i class="bi bi-check-circle-fill"/></button><div v-if="form.payment==='paypal'" class="paypal-box">
    <div class="paypal-benefit"><div class="paypal-benefit-icon"><i class="bi bi-truck"/></div><div><strong>Thanh toán trước — miễn phí vận chuyển</strong><small>Chọn PayPal để được miễn phí phí vận chuyển cho đơn hàng này.</small></div><i class="bi bi-check-circle-fill"/></div>
    <div class="paypal-rate-card">
        <div class="paypal-rate-head"><span><i class="bi bi-currency-exchange"/> Thông tin quy đổi PayPal</span><strong>USD</strong></div>
        <div class="paypal-rate-row"><span>Giá trị đơn hàng</span><strong>{{ formatPrice(subtotal) }}</strong></div>
        <div class="paypal-rate-row"><span>Phí vận chuyển</span><strong class="is-free">Miễn phí</strong></div>
        <div class="paypal-rate-row paypal-rate-total"><span>Tổng thanh toán</span><strong>{{ formatPrice(total) }}</strong></div>
        <div class="paypal-rate-divider"/>
        <div class="paypal-rate-row"><span>Tỷ giá quy đổi</span><strong>{{ paypalRateLabel }}</strong></div>
        <div class="paypal-rate-row"><span>Số tiền thanh toán PayPal</span><strong class="paypal-usd">${{ paypalUsd.toFixed(2) }} USD</strong></div>
        <small class="paypal-rate-note">Số tiền USD được tính từ tổng thanh toán VND theo tỷ giá quy đổi đang áp dụng tại TechStore.</small>
    </div>
    <div v-if="paypalError" class="checkout-error"><i class="bi bi-exclamation-circle"/> {{ paypalError }}</div>
    <div v-else-if="paypalLoading" class="paypal-loading"><span class="spinner-border spinner-border-sm"/> Đang xử lý thanh toán...</div>
    <div ref="paypalContainer" class="paypal-container"/>
</div></div><button v-if="form.payment==='cod'" type="submit" class="place-order-btn">Đặt hàng <i class="bi bi-arrow-right"/></button></div></aside></form></template>
        <section v-else class="checkout-empty"><div><i class="bi bi-bag-x"/></div><h2>Giỏ hàng đang trống</h2><p>Hãy thêm sản phẩm trước khi tiến hành thanh toán.</p><Link href="/products" class="success-btn">Khám phá sản phẩm <i class="bi bi-arrow-right"/></Link></section>
    </div></div>
</template>

